template<class Row> void test_type() {
    using Value = typename Row::value_type;
    for (auto [h,w] : {std::pair{32,128}, {65,65}, {129,33}, {33,129}}) {
        std::vector<Row> input(h, Row(w, Value{}));
        for (int i=0;i<h;++i)for(int j=0;j<w;++j)input[i][j]=static_cast<Value>(i*257+j*137);
        const auto before = input;
        for (int mode : {0,1,3}) {
            std::vector<Row> expected(w,Row(h,Value{}));
            for(int i=0;i<h;++i)for(int j=0;j<w;++j)
                if(mode==1)expected[j][h-1-i]=input[i][j];
                else if(mode==3)expected[w-1-j][i]=input[i][j];
                else expected[j][i]=input[i][j];
            for (int budget=0;budget<w+2;++budget) {
                current_h=h;current_w=w;current_mode=mode;current_budget=budget;
                const auto owned=live.load(); remaining=budget;
                try {
                    auto output=mode==0?transpose(input):mode==1?rotate_90r(input):rotate_90l(input);
                    remaining=-1;check(output==expected);
                } catch(const std::bad_alloc&) {remaining=-1;++failures;}
                check(input==before);check(live.load()==owned);
            }
        }
    }
}
